import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { casesAPI, openingsAPI } from '../services/api';
import CaseCard from '../components/CaseCard';
import SplashScreen from '../components/SplashScreen';
import CaseOpeningAnimation from '../components/CaseOpeningAnimation';
import ImageWithFallback from '../components/ImageWithFallback';

const CasesPage = () => {
  const { balance, updateBalance } = useAuth();
  const [cases, setCases] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showSplash, setShowSplash] = useState(true);
  const [showAnimation, setShowAnimation] = useState(false);
  const [animationCaseId, setAnimationCaseId] = useState(null);
  const [wonItemFromAnimation, setWonItemFromAnimation] = useState(null);

  useEffect(() => {
    const fetchCases = async () => {
      try {
        const casesResponse = await casesAPI.getCases();
        setCases(casesResponse.data);
      } catch (error) {
        console.error('Error fetching cases:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchCases();
  }, []);

  const handleOpenCase = async (caseId) => {
    // Set the case ID for animation and show it
    setAnimationCaseId(caseId);
    setShowAnimation(true);
  };

  const handleAnimationComplete = (wonItem) => {
    setWonItemFromAnimation(wonItem);
    // Update balance after animation
    updateBalance();
  };

  const handleAnimationClose = () => {
    setShowAnimation(false);
    setWonItemFromAnimation(null);
    setAnimationCaseId(null);
  };

  // Hide splash after a delay (or after data loads, but we already have a timeout in SplashScreen)
  const handleSplashFinish = () => {
    setShowSplash(false);
  };

  if (showSplash) {
    return <SplashScreen onFinish={handleSplashFinish} />;
  }

  if (loading) {
    return (
      <div className="container">
        <div className="row justify-content-center">
          <div className="col-md-4">
            <div className="text-center py-5">
              <div className="spinner-border text-primary" role="status">
                <span className="visually-hidden">Loading...</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="container">
      <h1 className="mb-4 gradient-text">Cases</h1>
      <div className="alert alert-info">
        Virtual currency — no real-money value
      </div>
      <div className="row mb-4">
        <div className="col-md-8">
          <h2>Balance: <span className="text-success">{balance.toLocaleString()} €</span></h2>
        </div>
      </div>
      <div className="row g-4">
        {cases.map(caseItem => (
          <div key={caseItem.id} className="col-md-4">
            <CaseCard
              case={caseItem}
              onOpen={handleOpenCase}
            />
          </div>
        ))}
      </div>

      {/* Case Opening Animation Overlay */}
      {showAnimation && (
        <div className="opening-overlay" onClick={handleAnimationClose}>
          <div className="opening-overlay-content">
            <CaseOpeningAnimation
              caseId={animationCaseId}
              onComplete={handleAnimationComplete}
              onClose={handleAnimationClose}
            />
          </div>
        </div>
      )}

      {/* Won Item Celebration (after animation closes) */}
      {wonItemFromAnimation && !showAnimation && (
        <div className="celebration-overlay">
          <div className="celebration-content">
            <h3>Congratulations!</h3>
            <p>You won: {wonItemFromAnimation.name}</p>
            <div className="won-item-image">
              <ImageWithFallback
                src={wonItemFromAnimation.image_url}
                alt={wonItemFromAnimation.name}
                className="celebration-item-image"
                style={{ width: '120px', height: '120px' }}
              />
            </div>
            <button className="btn btn-primary mt-3" onClick={() => setWonItemFromAnimation(null)}>
              Close
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default CasesPage;
